if(a==='preview-order-cert'){loading(true);const result=await rpc('previewOrderCertificate',{id:b.dataset.id});savePayload(result);await refresh();toast('PDF downloaded for your review. Approve it in the delivery queue after checking.');return;}
if(['approve-template','retire-template','approve-order-cert','rebuild-cert'].includes(a)){const messages={'approve-template':['Approve this version?','Confirm you opened the sample PDF and checked the design, wording and authorised signatories. Approved versions cannot be edited.'],'retire-template':['Retire this template?','New generation and pending delivery with this version will stop. Previously sent certificates remain available.'],'approve-order-cert':['Approve this participant PDF?','Confirm you downloaded this PDF and checked the recipient, programme, dates and signatories. It becomes eligible for delivery.'],'rebuild-cert':['Rebuild the pending PDF?','The old file will be retained in history. A new PDF uses the current approved template and must be reviewed again. No email is sent by this action.']};const m=messages[a];openDialog('<h2>'+m[0]+'</h2><p>'+m[1]+'</p>'+btn('Confirm','confirm-document-action','btn',`data-kind="${a}" data-id="${esc(b.dataset.id)}"`));return;}
if(a==='confirm-document-action'){const actions={'approve-template':'approveCertificateTemplate','retire-template':'retireCertificateTemplate','approve-order-cert':'approveOrderCertificate','rebuild-cert':'rebuildPendingCertificate'};loading(true);await perform(actions[b.dataset.kind],{id:b.dataset.id,confirm:true});closeDialog();return;}

