if(a==='import-participants'){openDialog('<h2>Import paid participants?</h2><p>Read the Import sheet and create verified, incomplete programme orders. The result includes row numbers and reasons only.</p>'+btn('Import now','confirm-import-participants','btn'));return;}
if(a==='confirm-import-participants'){loading(true);const result=await perform('importPaidParticipants',{},'Import finished.');closeDialog();openDialog('<h2>Import result</h2><p>Created: '+result.created+' · Skipped: '+result.skipped+' · Errors: '+result.errors+'</p><pre>'+esc(JSON.stringify(result.rows||[],null,2))+'</pre>');return;}
if(a==='mark-complete'){const ids=(b.dataset.id||'').split(',').filter(Boolean);openDialog('<h2>Mark '+ids.length+' participant(s) complete?</h2><p>This queues eligible certificates. Confirm only after checking attendance or completion evidence.</p>'+btn('Confirm completion','confirm-mark-complete','btn','data-ids="'+esc(ids.join(','))+'"'));return;}
