if(a==='open-protected'){loading(true);const result=await rpc('openProtectedItem',{itemType:b.dataset.type,itemId:b.dataset.id});if(result.base64)savePayload(result);else openDialog(`<h2>Your access is ready</h2><p>This link opens the resource or programme on its host.</p><a class="btn" href="${esc(result.url)}" target="_blank" rel="noopener noreferrer">Open now ${icon('out')}</a>`);return;}
if(a==='load-private-video'){loading(true);const c=S.courses.find(x=>x.id===S.selected),l=c.lessons[S.lesson],result=await rpc('lessonMedia',{courseId:c.id,lessonId:l.id});releaseVideo();S.videoObjectUrl=URL.createObjectURL(payloadBlob(result));$('#private-video-player').src=S.videoObjectUrl;b.hidden=true;return;}

